import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import "../styles/page.css";
import { BUILT_IN_ACTIONS, DEFAULT_SETTINGS } from "../shared/defaults";
import { DEFAULT_MODEL_BY_PROVIDER } from "../shared/models";
import { getSettings, saveSettings } from "../shared/storage";
import type { AiProvider, AssistantSettings, CustomAction } from "../shared/types";
import { ModelPicker } from "./ModelPicker";

function SettingsApp() {
  const [settings, setSettings] = useState<AssistantSettings>(DEFAULT_SETTINGS);
  const [secrets, setSecrets] = useState<Record<string, { apiKey?: string; baseUrl?: string }>>({});
  const [keyInputMap, setKeyInputMap] = useState<Record<string, string>>({});
  const [saved, setSaved] = useState(false);
  const [lightModelsOnly, setLightModelsOnly] = useState(true);
  const [addOpen, setAddOpen] = useState(false);
  const [newAction, setNewAction] = useState({ name: "", promptTemplate: "", category: "Custom", color: "#2563eb", pinned: true, isTranslation: false });

  useEffect(() => {
    void getSettings().then(setSettings);
    void chrome.storage.local.get(["providerSecrets"]).then((res) => {
      setSecrets((res.providerSecrets as Record<string, { apiKey?: string; baseUrl?: string }>) || {});
    });
  }, []);

  async function persist(next = settings) {
    const currentProvider = next.provider.provider;
    const updatedSecrets = { ...secrets };

    for (const [prov, val] of Object.entries(keyInputMap)) {
      if (val !== "••••••••••••••••••••") {
        updatedSecrets[prov] = {
          ...updatedSecrets[prov],
          apiKey: val
        };
      }
    }

    const currentKey = keyInputMap[currentProvider] !== undefined && keyInputMap[currentProvider] !== "••••••••••••••••••••"
      ? keyInputMap[currentProvider]
      : secrets[currentProvider]?.apiKey;

    const nextSettings = {
      ...next,
      provider: {
        ...next.provider,
        apiKey: currentKey
      }
    };

    await chrome.storage.local.set({ providerSecrets: updatedSecrets });
    await saveSettings(nextSettings);

    setSecrets(updatedSecrets);
    setKeyInputMap({});

    setSaved(true);
    window.setTimeout(() => setSaved(false), 1200);
  }

  function updateAction(id: string, patch: Partial<CustomAction>) {
    setSettings((current) => ({
      ...current,
      customActions: current.customActions.map((action) => (action.id === id ? { ...action, ...patch } : action))
    }));
  }

  function moveLanguage(index: number, direction: -1 | 1) {
    const nextIndex = index + direction;
    if (nextIndex < 0 || nextIndex >= settings.translationLanguages.length) return;
    const next = [...settings.translationLanguages];
    const current = next[index];
    next[index] = next[nextIndex];
    next[nextIndex] = current;
    setSettings({ ...settings, translationLanguages: next });
  }

  const allActions = [...BUILT_IN_ACTIONS, ...settings.customActions];
  const isDark = settings.theme === "dark" || (settings.theme === "system" && window.matchMedia?.("(prefers-color-scheme: dark)").matches);
  const theme = {
    page: isDark ? "#101218" : "#f8fafd",
    surface: isDark ? "#1b1b1f" : "#ffffff",
    soft: isDark ? "#24262d" : "#f1f4f9",
    border: isDark ? "#444746" : "#dadce0",
    text: isDark ? "#e3e3e3" : "#202124",
    muted: isDark ? "#c4c7c5" : "#5f6368",
    input: isDark ? "#101218" : "#ffffff",
    accent: settings.defaultSelectionAction === "creative" ? "#9334e6" : "#1a73e8"
  };

  function addCustomAction() {
    if (!newAction.name.trim() || !newAction.promptTemplate.trim()) return;
    setSettings({
      ...settings,
      customActions: [
        ...settings.customActions,
        {
          id: crypto.randomUUID(),
          name: newAction.name.trim(),
          promptTemplate: newAction.promptTemplate.trim(),
          category: newAction.category.trim() || "Custom",
          color: newAction.color,
          pinned: newAction.pinned,
          isTranslation: newAction.isTranslation
        }
      ]
    });
    setNewAction({ name: "", promptTemplate: "", category: "Custom", color: "#2563eb", pinned: true, isTranslation: false });
    setAddOpen(false);
  }

  return (
    <main className="min-h-screen px-5 py-6" style={{ background: theme.page, color: theme.text, fontFamily: "Google Sans, Roboto, Arial, sans-serif" }}>
      <div className="mx-auto max-w-5xl">
        <header className="mb-6 flex flex-wrap items-center justify-between gap-3">
          <div>
            <h1 className="text-[28px] font-medium tracking-normal">AI Context Assistant</h1>
            <p className="mt-1 text-sm" style={{ color: theme.muted }}>Provider, prompt, theme, and sync settings.</p>
          </div>
          <button className="focus-ring inline-flex items-center gap-2 rounded-full px-5 py-2.5 text-sm font-medium text-white shadow-sm" style={{ background: theme.accent }} onClick={() => persist()}>
            {saved ? "Saved" : "Save changes"}
          </button>
        </header>

        <div className="grid gap-4 lg:grid-cols-[1fr_1.4fr]">
          <section className="rounded-[28px] border p-5 shadow-sm" style={{ background: theme.surface, borderColor: theme.border }}>
            <h2 className="text-sm font-medium uppercase tracking-wide" style={{ color: theme.muted }}>AI Provider</h2>
            <div className="mt-4 space-y-3">
              <label className="block text-sm font-semibold">
                Provider
                <select className="focus-ring mt-1 w-full rounded-2xl border px-4 py-3" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={settings.provider.provider} onChange={(event) => {
                  const provider = event.target.value as AiProvider;
                  setSettings({ ...settings, provider: { ...settings.provider, provider, model: DEFAULT_MODEL_BY_PROVIDER[provider] } });
                }}>
                  <option value="openai">OpenAI</option>
                  <option value="gemini">Gemini</option>
                  <option value="claude">Claude</option>
                  <option value="ollama">Local Ollama</option>
                </select>
              </label>
              <div className="block text-sm font-semibold">
                Model
                <ModelPicker
                  provider={settings.provider.provider}
                  value={settings.provider.model}
                  lightOnly={lightModelsOnly}
                  onLightOnlyChange={setLightModelsOnly}
                  onChange={(model) => setSettings({ ...settings, provider: { ...settings.provider, model } })}
                  theme={theme}
                />
              </div>
              {settings.provider.provider !== "ollama" ? (
                <label className="block text-sm font-semibold">
                  API key
                  <input
                    className="focus-ring mt-1 w-full rounded-2xl border px-4 py-3"
                    style={{ background: theme.input, borderColor: theme.border, color: theme.text }}
                    type="password"
                    value={
                      keyInputMap[settings.provider.provider] !== undefined
                        ? keyInputMap[settings.provider.provider]
                        : (secrets[settings.provider.provider]?.apiKey ? "••••••••••••••••••••" : "")
                    }
                    onChange={(event) => {
                      const val = event.target.value;
                      setKeyInputMap((prev) => ({ ...prev, [settings.provider.provider]: val }));
                    }}
                    onCopy={(e) => e.preventDefault()}
                    onCut={(e) => e.preventDefault()}
                    onDragStart={(e) => e.preventDefault()}
                    placeholder="API key"
                  />
                </label>
              ) : (
                <label className="block text-sm font-semibold">
                  Ollama URL
                  <input className="focus-ring mt-1 w-full rounded-2xl border px-4 py-3" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={settings.provider.baseUrl ?? "http://127.0.0.1:11434"} onChange={(event) => setSettings({ ...settings, provider: { ...settings.provider, baseUrl: event.target.value } })} />
                </label>
              )}
            </div>
          </section>

          <section id="custom-actions" className="rounded-[28px] border p-5 shadow-sm" style={{ background: theme.surface, borderColor: theme.border }}>
            <div className="flex items-center justify-between gap-3">
              <h2 className="text-sm font-medium uppercase tracking-wide" style={{ color: theme.muted }}>Custom AI Buttons</h2>
              <button className="focus-ring inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-medium" style={{ borderColor: theme.border, color: theme.accent }} onClick={() => setAddOpen(true)}>
                + Add
              </button>
            </div>
            <div className="mt-4 space-y-3">
              {settings.customActions.map((action) => (
                <article key={action.id} className="rounded-[22px] border p-4" style={{ background: theme.soft, borderColor: theme.border }}>
                  <div className="grid gap-2 md:grid-cols-[1fr_140px_90px_92px_36px]">
                    <input className="focus-ring rounded-2xl border px-4 py-2.5 text-sm font-medium" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={action.name} onChange={(event) => updateAction(action.id, { name: event.target.value })} />
                    <input className="focus-ring rounded-2xl border px-4 py-2.5 text-sm" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={action.category ?? "Custom"} onChange={(event) => updateAction(action.id, { category: event.target.value })} placeholder="Category" />
                    <input className="focus-ring rounded-2xl border px-2 py-2" style={{ background: theme.input, borderColor: theme.border }} type="color" value={action.color ?? "#2563eb"} onChange={(event) => updateAction(action.id, { color: event.target.value })} />
                    <label className="flex items-center justify-center gap-2 rounded-full border px-3 text-xs font-medium" style={{ background: theme.input, borderColor: theme.border }}><input type="checkbox" checked={Boolean(action.pinned)} onChange={(event) => updateAction(action.id, { pinned: event.target.checked })} /> Pin</label>
                    <button className="focus-ring grid place-items-center rounded-full border text-red-600" style={{ borderColor: theme.border }} onClick={() => setSettings({ ...settings, customActions: settings.customActions.filter((item) => item.id !== action.id) })}>
                      ×
                    </button>
                  </div>
                  <label className="mt-2 flex items-center gap-2 text-xs font-bold" style={{ color: theme.muted }}><input type="checkbox" checked={Boolean(action.isTranslation)} onChange={(event) => updateAction(action.id, { isTranslation: event.target.checked })} /> Show Translation Context field for this prompt</label>
                  <textarea className="focus-ring mt-2 min-h-24 w-full rounded-2xl border px-4 py-3 text-sm" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={action.promptTemplate} onChange={(event) => updateAction(action.id, { promptTemplate: event.target.value })} />
                </article>
              ))}
            </div>
          </section>

          <section className="rounded-[28px] border p-5 shadow-sm lg:col-span-2" style={{ background: theme.surface, borderColor: theme.border }}>
            <h2 className="text-sm font-medium uppercase tracking-wide" style={{ color: theme.muted }}>Experience</h2>
            <div className="mt-4 grid gap-3 md:grid-cols-3">
              <label className="text-sm font-medium">Theme<select className="focus-ring mt-1 w-full rounded-2xl border px-4 py-3" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={settings.theme} onChange={(event) => setSettings({ ...settings, theme: event.target.value as AssistantSettings["theme"] })}><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label>
              <label className="text-sm font-medium">Default Selection Action<select className="focus-ring mt-1 w-full rounded-2xl border px-4 py-3" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={settings.defaultSelectionAction} onChange={(event) => setSettings({ ...settings, defaultSelectionAction: event.target.value })}><option value="normal">Normal</option><option value="creative">Creative</option>{allActions.map((action) => <option key={action.id} value={action.id}>{action.name}</option>)}</select></label>
              <label className="text-sm font-medium">Default target<select className="focus-ring mt-1 w-full rounded-2xl border px-4 py-3" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={settings.defaultTargetLanguage} onChange={(event) => setSettings({ ...settings, defaultTargetLanguage: event.target.value })}>{settings.translationLanguages.map((language) => <option key={language} value={language}>{language}</option>)}</select></label>
            </div>
            <div className="mt-4 rounded-xl border p-3" style={{ background: theme.soft, borderColor: theme.border }}>
              <div className="text-xs font-bold uppercase tracking-wide" style={{ color: theme.muted }}>Keyboard Shortcut</div>
              <p className="mt-1 text-sm" style={{ color: theme.muted }}>Default: Alt + O. Chrome controls extension shortcut customization.</p>
              <button className="focus-ring mt-3 rounded-xl px-3 py-2 text-sm font-bold text-white" style={{ background: theme.accent }} onClick={() => chrome.tabs.create({ url: "chrome://extensions/shortcuts" })}>
                Customize shortcut
              </button>
            </div>
            <div className="mt-4 rounded-xl border p-3" style={{ background: theme.soft, borderColor: theme.border }}>
              <div className="mb-2 text-xs font-bold uppercase tracking-wide" style={{ color: theme.muted }}>Translation Languages</div>
              <div className="flex flex-wrap gap-2">
                {settings.translationLanguages.map((language, index) => (
                  <span key={language} className="inline-flex items-center gap-1 rounded-full px-3 py-1 text-sm font-semibold" style={{ background: theme.input }}>
                    {language}
                    <button onClick={() => moveLanguage(index, -1)}>↑</button>
                    <button onClick={() => moveLanguage(index, 1)}>↓</button>
                    <button className="text-red-600" onClick={() => setSettings({ ...settings, translationLanguages: settings.translationLanguages.filter((item) => item !== language), defaultTargetLanguage: settings.defaultTargetLanguage === language ? "Arabic" : settings.defaultTargetLanguage })}>×</button>
                  </span>
                ))}
              </div>
            </div>
          </section>
        </div>
      </div>
      {addOpen && (
        <div className="fixed inset-0 z-50 grid place-items-center bg-black/45 px-4">
          <div className="w-full max-w-lg rounded-2xl border p-5 shadow-2xl" style={{ background: theme.surface, borderColor: theme.border, color: theme.text }}>
            <div className="mb-4">
              <h2 className="text-lg font-bold">Create Custom AI Button</h2>
              <p className="mt-1 text-sm" style={{ color: theme.muted }}>Add a reusable button by describing exactly what it should do.</p>
            </div>
            <div className="space-y-3">
              <label className="block text-sm font-semibold">
                Button name
                <input
                  autoFocus
                  className="focus-ring mt-1 w-full rounded-xl border px-3 py-2"
                  style={{ background: theme.input, borderColor: theme.border, color: theme.text }}
                  value={newAction.name}
                  onChange={(event) => setNewAction({ ...newAction, name: event.target.value })}
                  placeholder="Rewrite professionally"
                />
              </label>
              <label className="block text-sm font-semibold">
                What should this button do?
                <textarea
                  className="focus-ring mt-1 min-h-32 w-full rounded-xl border px-3 py-2"
                  style={{ background: theme.input, borderColor: theme.border, color: theme.text }}
                  value={newAction.promptTemplate}
                  onChange={(event) => setNewAction({ ...newAction, promptTemplate: event.target.value })}
                  placeholder="Rewrite the selected text in a professional, concise tone."
                />
              </label>
              <div className="grid gap-3 sm:grid-cols-2">
                <label className="block text-sm font-semibold">
                  Category
                  <input className="focus-ring mt-1 w-full rounded-xl border px-3 py-2" style={{ background: theme.input, borderColor: theme.border, color: theme.text }} value={newAction.category} onChange={(event) => setNewAction({ ...newAction, category: event.target.value })} />
                </label>
                <label className="block text-sm font-semibold">
                  Color
                  <input className="focus-ring mt-1 h-11 w-full rounded-xl border px-2 py-1" style={{ background: theme.input, borderColor: theme.border }} type="color" value={newAction.color} onChange={(event) => setNewAction({ ...newAction, color: event.target.value })} />
                </label>
              </div>
              <label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={newAction.pinned} onChange={(event) => setNewAction({ ...newAction, pinned: event.target.checked })} /> Pin this button in Tools</label>
              <label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={newAction.isTranslation} onChange={(event) => setNewAction({ ...newAction, isTranslation: event.target.checked })} /> This is a translation action</label>
            </div>
            <div className="mt-5 flex justify-end gap-2">
              <button className="focus-ring rounded-xl border px-4 py-2 text-sm font-bold" style={{ borderColor: theme.border }} onClick={() => setAddOpen(false)}>Cancel</button>
              <button className="focus-ring rounded-xl px-4 py-2 text-sm font-bold text-white" style={{ background: theme.accent }} onClick={addCustomAction}>Save Button</button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

createRoot(document.getElementById("root")!).render(<SettingsApp />);


