import type { AiProvider } from "../shared/types";
import { getModelColor, getProviderModels } from "../shared/models";

interface ModelPickerProps {
  provider: AiProvider;
  value: string;
  lightOnly: boolean;
  onLightOnlyChange: (lightOnly: boolean) => void;
  onChange: (modelId: string) => void;
  theme: {
    input: string;
    border: string;
    text: string;
    muted: string;
    soft: string;
    accent: string;
  };
}

export function ModelPicker({ provider, value, lightOnly, onLightOnlyChange, onChange, theme }: ModelPickerProps) {
  const models = getProviderModels(provider, lightOnly);

  return (
    <div className="mt-1">
      <label className="mb-2 flex items-center gap-2 text-xs font-medium" style={{ color: theme.muted }}>
        <input
          type="checkbox"
          checked={lightOnly}
          onChange={(event) => {
            const nextLightOnly = event.target.checked;
            onLightOnlyChange(nextLightOnly);
            const nextModels = getProviderModels(provider, nextLightOnly);
            if (!nextModels.some((model) => model.id === value) && nextModels[0]) {
              onChange(nextModels[0].id);
            }
          }}
        />
        Light models only
      </label>
      <div className="max-h-56 space-y-1 overflow-y-auto rounded-2xl border p-2" style={{ background: theme.soft, borderColor: theme.border }}>
        {models.map((model) => {
          const selected = value === model.id;
          return (
            <button
              key={model.id}
              type="button"
              className="focus-ring flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm transition"
              style={{
                background: selected ? theme.input : "transparent",
                border: selected ? `1px solid ${theme.accent}` : "1px solid transparent",
                color: theme.text
              }}
              onClick={() => onChange(model.id)}
            >
              <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: getModelColor(model.id, provider) }} />
              <span className="min-w-0 flex-1 truncate font-medium">{model.id}</span>
              <span className="shrink-0 text-[11px] uppercase tracking-wide" style={{ color: theme.muted }}>
                {model.tier}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
